from typing import Any
import sqlalchemy as sa

class AstroMCPServer:
    """Servidor Model Context Protocol (MCP) para diagnóstico técnico y RAG."""
    def __init__(self, sql_dsn: str, vector_store):
        self.db = sa.create_engine(sql_dsn)
        self.vectors = vector_store

    def list_tools(self) -> list[dict[str, Any]]:
        return [
            {
                "name": "consultar_manual_rag",
                "description": "Busca procedimientos técnicos en manuales operativos de planta mediante embeddings.",
                "inputSchema": {
                    "type": "object",
                    "properties": {"consulta": {"type": "string"}, "top_k": {"type": "integer", "default": 4}},
                    "required": ["consulta"]
                }
            },
            {
                "name": "estado_lotes_sap_sql",
                "description": "Consulta de solo lectura del estado de lotes e-CF y servicios en SQL Server.",
                "inputSchema": {
                    "type": "object",
                    "properties": {"fecha": {"type": "string"}},
                    "required": ["fecha"]
                }
            }
        ]

    def call_tool(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        if name == "consultar_manual_rag":
            docs = self.vectors.similarity_search(arguments["consulta"], k=arguments.get("top_k", 4))
            return {"matches": [{"source": d.metadata["doc_id"], "excerpt": d.page_content} for d in docs]}
        if name == "estado_lotes_sap_sql":
            with self.db.connect() as conn:
                rows = conn.execute(
                    sa.text("SELECT lote_id, estado, duracion_seg FROM vw_monitoreo_lotes WHERE fecha = :f"),
                    {"f": arguments["fecha"]}
                ).mappings().all()
                return {"lotes": [dict(r) for r in rows]}
